import"./chunk-ZW5NV4UO.js";var e={en:{title:"Canadian politics on Mastodon: journalists and civic news",description:"Follow Canadian politics through journalism, public policy and civic news. Preview English-language accounts and hashtags before building your Mastodon feed.",heading:"Canadian politics on Mastodon",listTitle:"Canadian Politics",intro:["Follow Canadian politics through reporting on Parliament, provincial and municipal government, public policy and civic life. Start with established journalists, independent newsrooms and people explaining how public institutions work.","Choose accounts and hashtags, then preview their recent posts. The selection favors substantive reporting over constant outrage. Hashtags are open streams; leave them unchecked if you prefer a feed built only from selected accounts. A separate French edition is also available."],faq:[{q:"Do I need an account?",a:"You can browse and preview public posts without an account. Sign in with your Mastodon account to follow people and hashtags or create a list."},{q:"What kind of political coverage is included?",a:"Canadian civic reporting and policy explanation, including regional and Indigenous affairs. Extremist advocacy, hate, party recruitment and promotion of provincial independence are outside the selection. Neutral reporting on those subjects remains eligible. This selection does not guarantee equal representation across political viewpoints or filter future posts."},{q:"How do I get onto this list?",a:"This topic focuses on established public voices and organizations with sustained, substantive coverage. Small personal accounts are left out for privacy, and discovery preferences are checked. For help or removal, contact @mawkingbird@mastodon.social."}]},fr:{title:"Politique canadienne sur Mastodon\xA0: actualit\xE9s et voix \xE0 suivre",description:"Explore la politique canadienne en fran\xE7ais\xA0: journalisme, vie civique et d\xE9bats publics. Choisis des comptes et des hashtags pour ton fil Mastodon.",heading:"La politique canadienne sur Mastodon",listTitle:"Politique canadienne",intro:["Que se passe-t-il \xE0 Ottawa, \xE0 Qu\xE9bec et dans les municipalit\xE9s\u202F? Retrouve des reportages, des analyses et des explications sur les d\xE9cisions qui touchent la vie quotidienne. Cette s\xE9lection en fran\xE7ais privil\xE9gie les sources publiques \xE9tablies et les \xE9changes de fond.","Choisis tes comptes et tes hashtags, puis consulte un aper\xE7u du fil. Les hashtags sont des flux ouverts\xA0: d\xE9coche-les si tu pr\xE9f\xE8res suivre uniquement les comptes s\xE9lectionn\xE9s. Trois comptes relaient automatiquement les articles de Radio-Canada, de La Presse et de L\u2019Actualit\xE9\u202F; ils ne sont pas affili\xE9s \xE0 ces m\xE9dias."],faq:[{q:"Faut-il un compte\u202F?",a:"Tu peux parcourir la s\xE9lection et lire les publications publiques sans compte. Connecte-toi avec ton compte Mastodon pour suivre des personnes et des hashtags ou cr\xE9er une liste."},{q:"Comment les sources sont-elles choisies\u202F?",a:"Nous cherchons des reportages et des explications sur la vie civique canadienne, sans extr\xE9misme, haine ni promotion de l\u2019ind\xE9pendance provinciale. Couvrir un d\xE9bat constitutionnel ne signifie pas soutenir une cause. La s\xE9lection ne promet ni un \xE9quilibre parfait entre les opinions ni un contr\xF4le des publications futures. Le hashtag PolitiqueCanadienne est encore peu utilis\xE9."},{q:"Comment figurer dans cette liste\u202F?",a:"Cette s\xE9lection privil\xE9gie les voix publiques \xE9tablies et les organisations qui traitent r\xE9guli\xE8rement du sujet. Les petits comptes personnels sont laiss\xE9s de c\xF4t\xE9 pour pr\xE9server leur tranquillit\xE9. Pour une question ou une demande de retrait, contacte @mawkingbird@mastodon.social."}]}};export{e as COPY};
